// svd2rust - Generate Rust register maps from SVD files.
// Original-style reimplementation.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

mod cli;
mod svd;
mod generate;
mod log_mini;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let prog = args.get(0).map(|s| s.as_str()).unwrap_or("svd2rust");
    let prog_name = Path::new(prog).file_name().and_then(|s| s.to_str()).unwrap_or("svd2rust").to_string();

    match cli::parse(&args[1..]) {
        cli::ParseResult::Help(kind) => {
            print!("{}", cli::render_help(&prog_name, kind));
            ExitCode::SUCCESS
        }
        cli::ParseResult::Version => {
            println!("svd2rust 0.37.1 (e29353d 2026-03-03)");
            ExitCode::SUCCESS
        }
        cli::ParseResult::Error(err) => {
            eprintln!("error: {}", err);
            eprintln!();
            eprintln!("Usage: {} [OPTIONS]", prog_name);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            ExitCode::from(2)
        }
        cli::ParseResult::Opts(opts) => run(opts),
    }
}

fn run(opts: cli::Options) -> ExitCode {
    log_mini::init(opts.log_level);

    log_mini::info("svd2rust", "Parsing device from SVD file");

    // Read input
    let input = match opts.input.as_deref() {
        Some(p) => {
            match fs::read_to_string(p) {
                Ok(s) => s,
                Err(e) => {
                    log_mini::error(
                        "svd2rust",
                        &format!("Cannot open the SVD file\n    \n    Caused by:\n        {}", e),
                    );
                    return ExitCode::from(1);
                }
            }
        }
        None => {
            let mut s = String::new();
            if io::stdin().read_to_string(&mut s).is_err() {
                log_mini::error("svd2rust", "Cannot read stdin");
                return ExitCode::from(1);
            }
            s
        }
    };

    // Parse SVD
    let device = match svd::parse_device(&input) {
        Ok(d) => d,
        Err(e) => {
            log_mini::error(
                "svd2rust",
                &format!("Error parsing SVD XML file\n    \n    Caused by:\n        {}", e),
            );
            return ExitCode::from(0);
        }
    };

    // Validate target
    if let Some(t) = &opts.target {
        if !matches!(t.as_str(), "cortex-m" | "msp430" | "riscv" | "xtensa-lx" | "mips" | "none") {
            log_mini::error(
                "svd2rust",
                &format!(
                    "Failed to deserialize value\n    \n    Caused by:\n        unknown variant `{}`, expected one of `cortex-m`, `msp430`, `riscv`, `xtensa-lx`, `mips`, `none`",
                    t
                ),
            );
            return ExitCode::from(1);
        }
    }

    log_mini::info("svd2rust", "Rendering device");

    let output_dir: PathBuf = opts
        .output_dir
        .clone()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));

    if let Err(e) = fs::create_dir_all(&output_dir) {
        log_mini::error("svd2rust", &format!("Cannot create output directory: {}", e));
        return ExitCode::from(1);
    }

    let target = opts.target.as_deref().unwrap_or("cortex-m");
    let make_mod = opts.make_mod;

    let (lib_rs, build_rs, device_x) = generate::render(&device, target, &opts);
    let main_file = if make_mod { "mod.rs" } else { "lib.rs" };
    if let Err(e) = fs::write(output_dir.join(main_file), lib_rs) {
        log_mini::error("svd2rust", &format!("Cannot write {}: {}", main_file, e));
        return ExitCode::from(1);
    }
    if !make_mod {
        if let Err(e) = fs::write(output_dir.join("build.rs"), build_rs) {
            log_mini::error("svd2rust", &format!("Cannot write build.rs: {}", e));
            return ExitCode::from(1);
        }
        if let Err(e) = fs::write(output_dir.join("device.x"), device_x) {
            log_mini::error("svd2rust", &format!("Cannot write device.x: {}", e));
            return ExitCode::from(1);
        }
    }
    let _ = io::stdout().flush();
    ExitCode::SUCCESS
}
EOF
