// Manual CLI argument parser mimicking the original help/behavior.

use std::collections::HashMap;

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub input: Option<String>,
    pub output_dir: Option<String>,
    pub config: Option<String>,
    pub settings: Option<String>,
    pub edition: Option<String>,
    pub target: Option<String>,
    pub atomics: bool,
    pub atomics_feature: Option<String>,
    pub ignore_groups: bool,
    pub keep_list: bool,
    pub generic_mod: bool,
    pub feature_group: bool,
    pub feature_peripheral: bool,
    pub ident_format: Vec<String>,
    pub ident_formats_theme: Option<String>,
    pub field_names_for_enums: bool,
    pub max_cluster_size: bool,
    pub impl_debug: bool,
    pub impl_debug_feature: Option<String>,
    pub impl_defmt: Option<String>,
    pub make_mod: bool,
    pub skip_crate_attributes: bool,
    pub strict: bool,
    pub source_type: Option<String>,
    pub reexport_core_peripherals: bool,
    pub reexport_interrupt: bool,
    pub base_address_shift: Option<String>,
    pub log_level: Option<String>,
}

#[derive(Clone, Copy, Debug)]
pub enum HelpKind {
    Short,
    Long,
}

pub enum ParseResult {
    Opts(Options),
    Help(HelpKind),
    Version,
    Error(String),
}

fn need_value(opt: &str) -> Result<(), String> {
    Err(format!("a value is required for '{}' but none was supplied", opt))
}

pub fn parse(args: &[String]) -> ParseResult {
    let mut opts = Options::default();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        // Handle --long=value or --long value
        if a == "--help" {
            return ParseResult::Help(HelpKind::Long);
        }
        if a == "-h" {
            return ParseResult::Help(HelpKind::Short);
        }
        if a == "--version" || a == "-V" {
            return ParseResult::Version;
        }
        // Helper to pull value for long option
        let take_long = |prefix: &str, a: &str| -> Option<(Option<String>, bool)> {
            if a == prefix {
                // expect next arg
                Some((None, false))
            } else if let Some(rest) = a.strip_prefix(&format!("{}=", prefix)) {
                Some((Some(rest.to_string()), true))
            } else {
                None
            }
        };
        // Simplify: custom matches
        let mut matched = true;
        if a == "-i" {
            if i + 1 >= args.len() {
                return ParseResult::Error("a value is required for '-i <FILE>' but none was supplied".to_string());
            }
            opts.input = Some(args[i + 1].clone());
            i += 2;
            continue;
        } else if let Some(rest) = a.strip_prefix("-i") {
            if !rest.is_empty() {
                opts.input = Some(rest.to_string());
                i += 1;
                continue;
            } else { matched = false; }
        } else { matched = false; }
        let _ = matched;

        if let Some((v, used)) = take_long("--output-dir", a) {
            if let Some(v) = v { opts.output_dir = Some(v); i += 1; continue; }
            if i + 1 >= args.len() { return ParseResult::Error("a value is required for '--output-dir <PATH>' but none was supplied".to_string()); }
            opts.output_dir = Some(args[i+1].clone()); i += 2; continue;
            #[allow(unreachable_code)] let _ = used;
        }
        if a == "-o" {
            if i + 1 >= args.len() { return ParseResult::Error("a value is required for '--output-dir <PATH>' but none was supplied".to_string()); }
            opts.output_dir = Some(args[i+1].clone()); i += 2; continue;
        }
        if let Some(rest) = a.strip_prefix("-o") { opts.output_dir = Some(rest.to_string()); i += 1; continue; }

        if let Some((v, _)) = take_long("--config", a) {
            if let Some(v) = v { opts.config = Some(v); i += 1; continue; }
            if i + 1 >= args.len() { return ParseResult::Error("a value is required for '--config <TOML_FILE>' but none was supplied".to_string()); }
            opts.config = Some(args[i+1].clone()); i += 2; continue;
        }
        if a == "-c" {
            if i + 1 >= args.len() { return ParseResult::Error("a value is required for '--config <TOML_FILE>' but none was supplied".to_string()); }
            opts.config = Some(args[i+1].clone()); i += 2; continue;
        }
        if let Some(rest) = a.strip_prefix("-c") { opts.config = Some(rest.to_string()); i += 1; continue; }

        macro_rules! take_required {
            ($flag:literal, $field:ident, $name:literal) => {
                if a == $flag {
                    if i + 1 >= args.len() { return ParseResult::Error(format!("a value is required for '{}' but none was supplied", $name)); }
                    opts.$field = Some(args[i+1].clone());
                    i += 2; continue;
                }
                if let Some(rest) = a.strip_prefix(&format!("{}=", $flag)) { opts.$field = Some(rest.to_string()); i += 1; continue; }
            };
        }

        take_required!("--settings", settings, "--settings <YAML_FILE>");
        take_required!("--edition", edition, "--edition <YEAR>");
        take_required!("--target", target, "--target <ARCH>");
        take_required!("--atomics-feature", atomics_feature, "--atomics-feature <FEATURE>");
        take_required!("--ident-formats-theme", ident_formats_theme, "--ident-formats-theme <THEME>");
        take_required!("--impl-debug-feature", impl_debug_feature, "--impl-debug-feature <FEATURE>");
        take_required!("--impl-defmt", impl_defmt, "--impl-defmt <FEATURE>");
        take_required!("--source-type", source_type, "--source-type <source_type>");
        take_required!("--base-address-shift", base_address_shift, "--base-address-shift <base_address_shift>");
        take_required!("--log", log_level, "--log <log_level>");

        // -b / -l / -f short forms
        if a == "-b" {
