// Minimal log mimicking env_logger's default format: "[LEVEL MODULE] message"

use std::sync::atomic::{AtomicU8, Ordering};

static LEVEL: AtomicU8 = AtomicU8::new(3); // info

fn level_num(name: &str) -> u8 {
    match name {
        "off" => 0,
        "error" => 1,
        "warn" => 2,
        "info" => 3,
        "debug" => 4,
        "trace" => 5,
        _ => 3,
    }
}

pub fn init(cli_level: Option<String>) {
    let level = if let Some(l) = cli_level {
        level_num(&l)
    } else if let Ok(v) = std::env::var("RUST_LOG") {
        let v = v.trim().to_lowercase();
        level_num(&v)
    } else {
        3
    };
    LEVEL.store(level, Ordering::SeqCst);
}

fn enabled(needed: u8) -> bool {
    LEVEL.load(Ordering::SeqCst) >= needed
}

pub fn info(module: &str, msg: &str) {
    if enabled(3) {
        eprintln!("[INFO  {}] {}", module, msg);
    }
}

pub fn warn(module: &str, msg: &str) {
    if enabled(2) {
        eprintln!("[WARN  {}] {}", module, msg);
    }
}

pub fn error(module: &str, msg: &str) {
    if enabled(1) {
        eprintln!("[ERROR {}] {}", module, msg);
    }
}

#[allow(dead_code)]
pub fn debug(module: &str, msg: &str) {
    if enabled(4) {
        eprintln!("[DEBUG {}] {}", module, msg);
    }
}
