// Very minimal SVD XML parser/data model.

use std::collections::BTreeMap;

#[derive(Debug, Clone, Default)]
pub struct Device {
    pub name: String,
    pub description: Option<String>,
    pub width: Option<u32>,
    pub peripherals: Vec<Peripheral>,
}

#[derive(Debug, Clone, Default)]
pub struct Peripheral {
    pub name: String,
    pub description: Option<String>,
    pub base_address: u64,
    pub registers: Vec<Register>,
    pub interrupts: Vec<Interrupt>,
}

#[derive(Debug, Clone, Default)]
pub struct Interrupt {
    pub name: String,
    pub description: Option<String>,
    pub value: u32,
}

#[derive(Debug, Clone, Default)]
pub struct Register {
    pub name: String,
    pub description: Option<String>,
    pub address_offset: u64,
    pub size: u32,
    pub access: Option<String>,
    pub reset_value: u64,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone, Default)]
pub struct Field {
    pub name: String,
    pub description: Option<String>,
    pub bit_offset: u32,
    pub bit_width: u32,
    pub access: Option<String>,
}

pub fn parse_device(xml: &str) -> Result<Device, String> {
    let xml = xml.trim();
    if xml.is_empty() {
        return Err("the document does not have a root node".to_string());
    }
    let mut p = Parser::new(xml);
    p.skip_prologue();
    p.skip_whitespace();
    if p.pos >= p.input.len() {
        return Err("the document does not have a root node".to_string());
    }
    // Expect <device>
    let node = p.parse_node()?;
    if node.name != "device" {
        return Err(format!("root element is '{}', expected 'device'", node.name));
    }
    Ok(device_from_node(&node))
}

fn device_from_node(n: &Node) -> Device {
    let mut d = Device::default();
    d.name = text(n, "name").unwrap_or_default();
    d.description = text(n, "description");
    d.width = text(n, "width").and_then(|s| parse_u32(&s));
    if let Some(ps) = child(n, "peripherals") {
        for p in children(ps, "peripheral") {
            d.peripherals.push(peripheral_from_node(p));
        }
    }
    d
}

fn peripheral_from_node(n: &Node) -> Peripheral {
    let mut p = Peripheral::default();
    p.name = text(n, "name").unwrap_or_default();
    p.description = text(n, "description");
    p.base_address = text(n, "baseAddress")
        .and_then(|s| parse_u64(&s))
        .unwrap_or(0);
    if let Some(rs) = child(n, "registers") {
        for r in children(rs, "register") {
            p.registers.push(register_from_node(r));
        }
    }
    for it in children(n, "interrupt") {
        let mut iv = Interrupt::default();
        iv.name = text(it, "name").unwrap_or_default();
        iv.description = text(it, "description");
        iv.value = text(it, "value").and_then(|s| parse_u32(&s)).unwrap_or(0);
        p.interrupts.push(iv);
    }
    p
}

fn register_from_node(n: &Node) -> Register {
    let mut r = Register::default();
    r.name = text(n, "name").unwrap_or_default();
    r.description = text(n, "description");
    r.address_offset = text(n, "addressOffset").and_then(|s| parse_u64(&s)).unwrap_or(0);
    r.size = text(n, "size").and_then(|s| parse_u32(&s)).unwrap_or(32);
    r.access = text(n, "access");
    r.reset_value = text(n, "resetValue").and_then(|s| parse_u64(&s)).unwrap_or(0);
    if let Some(fs) = child(n, "fields") {
        for f in children(fs, "field") {
            let mut fv = Field::default();
            fv.name = text(f, "name").unwrap_or_default();
            fv.description = text(f, "description");
            fv.access = text(f, "access");
            if let Some(br) = text(f, "bitRange") {
                // format: [msb:lsb]
                let trimmed = br.trim_start_matches('[').trim_end_matches(']');
                if let Some((msb, lsb)) = trimmed.split_once(':') {
                    let (m, l) = (
                        parse_u32(msb.trim()).unwrap_or(0),
                        parse_u32(lsb.trim()).unwrap_or(0),
                    );
                    fv.bit_offset = l;
                    fv.bit_width = m - l + 1;
                }
            } else if let Some(off) = text(f, "bitOffset") {
                fv.bit_offset = parse_u32(&off).unwrap_or(0);
                fv.bit_width = text(f, "bitWidth").and_then(|s| parse_u32(&s)).unwrap_or(1);
            } else if let Some(lsb) = text(f, "lsb") {
                let l = parse_u32(&lsb).unwrap_or(0);
                let m = text(f, "msb").and_then(|s| parse_u32(&s)).unwrap_or(l);
                fv.bit_offset = l;
                fv.bit_width = m - l + 1;
            }
            r.fields.push(fv);
        }
    }
    r
}

fn parse_u32(s: &str) -> Option<u32> {
    let s = s.trim();
    if let Some(hx) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u32::from_str_radix(hx, 16).ok()
    } else if let Some(bn) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u32::from_str_radix(bn, 2).ok()
    } else {
        s.parse().ok()
    }
}

fn parse_u64(s: &str) -> Option<u64> {
    let s = s.trim();
    if let Some(hx) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(hx, 16).ok()
    } else if let Some(bn) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u64::from_str_radix(bn, 2).ok()
    } else {
        s.parse().ok()
    }
}

// --- Tiny XML DOM ---

#[derive(Debug, Default)]
pub struct Node {
    pub name: String,
    pub attrs: BTreeMap<String, String>,
    pub children: Vec<Node>,
    pub text: String,
}

fn child<'a>(n: &'a Node, name: &str) -> Option<&'a Node> {
    n.children.iter().find(|c| c.name == name)
}
fn children<'a>(n: &'a Node, name: &'a str) -> impl Iterator<Item = &'a Node> {
    n.children.iter().filter(move |c| c.name == name)
}
fn text(n: &Node, name: &str) -> Option<String> {
    child(n, name).map(|c| c.text.trim().to_string())
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Self { input: s.as_bytes(), pos: 0 } }
    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn skip_prologue(&mut self) {
        self.skip_whitespace();
        while self.pos + 1 < self.input.len() && self.input[self.pos] == b'<' && (self.input[self.pos+1] == b'?' || self.input[self.pos+1] == b'!') {
            if self.input[self.pos+1] == b'?' {
                // find ?>
                while self.pos + 1 < self.input.len() && !(self.input[self.pos] == b'?' && self.input[self.pos+1] == b'>') {
                    self.pos += 1;
                }
                self.pos += 2;
            } else {
                // <!-- comment --> or <!DOCTYPE ...>
                if self.input[self.pos..].starts_with(b"<!--") {
                    self.pos += 4;
                    while self.pos + 2 < self.input.len() && !self.input[self.pos..].starts_with(b"-->") {
                        self.pos += 1;
                    }
                    self.pos += 3;
                } else {
                    while self.pos < self.input.len() && self.input[self.pos] != b'>' {
                        self.pos += 1;
                    }
                    self.pos += 1;
                }
            }
            self.skip_whitespace();
        }
    }

    fn parse_node(&mut self) -> Result<Node, String> {
        if self.pos >= self.input.len() || self.input[self.pos] != b'<' {
            return Err("expected element".to_string());
        }
        self.pos += 1; // '<'
        let name = self.parse_name()?;
        let mut node = Node { name: name, ..Default::default() };
        // Parse attributes
        loop {
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                return Err("unexpected end".to_string());
            }
            let c = self.input[self.pos];
            if c == b'/' {
                // self-closing
                self.pos += 1;
                if self.pos >= self.input.len() || self.input[self.pos] != b'>' {
                    return Err("expected '>'".to_string());
                }
                self.pos += 1;
                return Ok(node);
            }
            if c == b'>' {
                self.pos += 1;
                break;
            }
            // attribute
            let attr_name = self.parse_name()?;
            self.skip_whitespace();
            if self.pos >= self.input.len() || self.input[self.pos] != b'=' {
                return Err("expected '='".to_string());
            }
            self.pos += 1;
            self.skip_whitespace();
            let q = self.input[self.pos];
            if q != b'"' && q != b'\'' {
                return Err("expected quoted attribute value".to_string());
            }
            self.pos += 1;
            let start = self.pos;
            while self.pos < self.input.len() && self.input[self.pos] != q {
                self.pos += 1;
            }
            let val = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("").to_string();
            self.pos += 1;
            node.attrs.insert(attr_name, val);
        }
        // Parse content until </name>
        let mut text_buf = Vec::<u8>::new();
        loop {
            if self.pos >= self.input.len() {
                return Err("unexpected end".to_string());
            }
            if self.input[self.pos] == b'<' {
                if self.pos + 1 < self.input.len() && self.input[self.pos+1] == b'/' {
                    // closing tag
                    self.pos += 2;
                    let _closing = self.parse_name()?;
                    self.skip_whitespace();
                    if self.pos >= self.input.len() || self.input[self.pos] != b'>' {
                        return Err("expected '>'".to_string());
                    }
                    self.pos += 1;
                    node.text = decode_entities(std::str::from_utf8(&text_buf).unwrap_or(""));
                    return Ok(node);
                }
                if self.input[self.pos..].starts_with(b"<!--") {
                    self.pos += 4;
                    while self.pos + 2 < self.input.len() && !self.input[self.pos..].starts_with(b"-->") {
                        self.pos += 1;
                    }
                    self.pos += 3;
                    continue;
                }
                if self.input[self.pos..].starts_with(b"<![CDATA[") {
                    self.pos += 9;
                    while self.pos + 2 < self.input.len() && !self.input[self.pos..].starts_with(b"]]>") {
                        text_buf.push(self.input[self.pos]);
                        self.pos += 1;
                    }
                    self.pos += 3;
                    continue;
                }
                // child element
                let child = self.parse_node()?;
                node.children.push(child);
            } else {
                text_buf.push(self.input[self.pos]);
                self.pos += 1;
            }
        }
    }

    fn parse_name(&mut self) -> Result<String, String> {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_ascii_alphanumeric() || c == b'_' || c == b':' || c == b'-' || c == b'.' {
                self.pos += 1;
            } else {
                break;
            }
        }
        if start == self.pos {
            return Err("expected name".to_string());
        }
        Ok(std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("").to_string())
    }
}

fn decode_entities(s: &str) -> String {
    s.replace("&lt;", "<")
     .replace("&gt;", ">")
     .replace("&amp;", "&")
     .replace("&quot;", "\"")
     .replace("&apos;", "'")
}
